// Generated by build.py. Keeps every app file on the device so the game opens with no connection,
// and refreshes them in the background whenever it is online. A new build gets a new cache name.
const CACHE='carrom-duel-454254b0d3fb';
const ASSETS=["./", "index.html", "manifest.webmanifest", "app/baloo2-latin.woff2", "app/lilita-one-latin.woff2", "app/icon-32.png", "app/icon-180.png", "app/icon-192.png", "app/icon-512.png", "app/icon-maskable-512.png"];
self.addEventListener('install',e=>{e.waitUntil(caches.open(CACHE).then(c=>c.addAll(ASSETS)).then(()=>self.skipWaiting()))});
self.addEventListener('activate',e=>{e.waitUntil(caches.keys().then(ks=>Promise.all(ks.filter(k=>k.startsWith('carrom-duel-')&&k!==CACHE).map(k=>caches.delete(k)))).then(()=>self.clients.claim()))});
self.addEventListener('fetch',e=>{
  const r=e.request;
  if(r.method!=='GET'||new URL(r.url).origin!==location.origin)return;
  e.respondWith(caches.open(CACHE).then(async c=>{
    const hit=await c.match(r,{ignoreSearch:true});
    const net=fetch(r).then(res=>{if(res&&res.ok)c.put(r,res.clone());return res}).catch(()=>null);
    if(hit){e.waitUntil(net);return hit}
    const res=await net;if(res)return res;
    if(r.mode==='navigate'){const page=await c.match('index.html');if(page)return page}
    return Response.error();
  }));
});
